   421  bool TGAHandler::canRead(QIODevice *device)
   422  {
   423      if (!device) {
   424          qWarning("TGAHandler::canRead() called with no device");
   425          return false;
   426      }
   427
   428      qint64 oldPos = device->pos();
   429      QByteArray head = device->read(TgaHeader::SIZE);
   430      int readBytes = head.size();
   431
   432      if (device->isSequential()) {
   433          for (int pos = readBytes - 1; pos >= 0; --pos) {
   434              device->ungetChar(head[pos]);
   435          }
   436      } else {
   437          device->seek(oldPos);
   438      }
   439
   440      if (readBytes < TgaHeader::SIZE) {
   441          return false;
   442      }
   443
   444      QDataStream stream(head);
   445      stream.setByteOrder(QDataStream::LittleEndian);
   446      TgaHeader tga;
   447      stream >> tga;
   448      return IsSupported(tga);
   449  }
