   451  QImageIOPlugin::Capabilities TGAPlugin::capabilities(QIODevice *device, const QByteArray &format) const
   452  {
   453      if (format == "tga") {
   454          return Capabilities(CanRead | CanWrite);
   455      }
   456      if (!format.isEmpty()) {
   457          return {};
   458      }
   459      if (!device->isOpen()) {
   460          return {};
   461      }
   462
   463      Capabilities cap;
   464      if (device->isReadable() && TGAHandler::canRead(device)) {
   465          cap |= CanRead;
   466      }
   467      if (device->isWritable()) {
   468          cap |= CanWrite;
   469      }
   470      return cap;
   471  }
